def binary_search(arr, key, low, high):
    if low > high:
        return -1, 1
    mid = (low + high) // 2
    if arr[mid] == key:
        return mid, 1
    elif key < arr[mid]:
        idx, calls = binary_search(arr, key, low, mid - 1)
        return idx, calls + 1
    else:
        idx, calls = binary_search(arr, key, mid + 1, high)
        return idx, calls + 1

