def clean_readings(data, low, high):
    orig_len = len(data)
    data[:] = [x for x in data if low <= x <= high]
    return orig_len - len(data)

def normalized_copy(data):
    if not data:
        return []
    mn = min(data)
    mx = max(data)
    if mn == mx:
        return [0.0] * len(data)
    return [round((x - mn) / (mx - mn), 2) for x in data]

